SELECT s.country, CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(AVG(ss.revenue), 2) AS avg_revenue, COUNT(ss.revenue) AS revenue_count FROM store_sales ss INNER JOIN products p ON p.id = ss.product_id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY s.country, CASE WHEN s.rating >= 4.0 THEN 'high' WHEN s.rating >= 2.1 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(ss.revenue), 2) > 62 ORDER BY country ASC
